sql:
select
    count(*) as total_login_count
from domino_dwd.dwd_usr_login_log_di;

select
    count(1) as recall_user
from domino_ods.user_recall_info;

select
    t.pay_amount_usd * 1.0 / nullif(t.successful_paying_user_count, 0) as paying_arpu
from (
    select
        sum(infull_amount) as pay_amount_usd,
        count(distinct user_id) as successful_paying_user_count
    from domino_dwd.dwd_trd_infull_order_di
    where infull_state = 1
) t;

select
    count(1) as total_order_cnt
from domino_dwd.dwd_trd_infull_order_di;

select
    sum(bank_money) as bank_money_amt
from domino_dwd.dwd_user_info_day;

select
    sum(money) as hand_money_amt
from domino_dwd.dwd_user_info_day;

select
    count(1) as first_new_device_cnt_did
from domino_ods.event_report_device_info;

select
    count(1) as total_reg_users
from domino_dwd.dwd_user_info_day;

SELECT COUNT(DISTINCT user_id) AS bankrupt_user_cnt
FROM domino_dwd.dwd_eco_user_money_log_di
WHERE end_money <= 0;

WITH login_user AS (
 SELECT DISTINCT DATE(login_time) AS dt,user_id FROM bkqp_dwd.dwd_login_log_detail_di
 WHERE login_time>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY) AND login_time<CURRENT_DATE()
), paid_user AS (
 SELECT DISTINCT DATE(infull_date) AS dt,user_id FROM bkqp_ods.fish_open_order
 WHERE state=1 AND infull_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY) AND infull_date<CURRENT_DATE()
)
SELECT l.dt,COUNT(DISTINCT p.user_id)*1.0/NULLIF(COUNT(DISTINCT l.user_id),0) AS metric_value
FROM login_user l LEFT JOIN paid_user p ON l.dt=p.dt AND l.user_id=p.user_id
GROUP BY l.dt;

select 
  sum(real_cost)/100 real_cost  -- 投放消耗(元)
from byqph5_dwd.dwd_adv_consume_di;

SELECT
    SUM(CASE WHEN money_flow_type = '金币消耗' THEN change_money ELSE 0 END) AS gold_cost
FROM byqph5_dwd.dwd_eco_money_log_hi;

SELECT sum(infull_num)
FROM lydr3d_dwd.dim_user_info_d
WHERE user_id = '${user_id}';

WITH active AS (
 SELECT DISTINCT user_id FROM gold_ods.app_login_log
 WHERE login_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY) AND login_date<CURRENT_DATE()
),orders AS (
 SELECT o.user_id,o.success_date,o.order_amount FROM gold_ods.infull_order o
 JOIN active a ON a.user_id=o.user_id
 WHERE o.order_status=1 AND o.success_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 180 DAY) AND o.success_date<CURRENT_DATE()
)
SELECT CURRENT_DATE() AS dt,user_id,SUM(order_amount) AS metric_value
FROM orders GROUP BY user_id;

WITH active AS (
 SELECT DISTINCT user_id FROM gold_ods.app_login_log
 WHERE login_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY) AND login_date<CURRENT_DATE()
),orders AS (
 SELECT o.user_id,o.success_date,o.order_amount FROM gold_ods.infull_order o
 JOIN active a ON a.user_id=o.user_id
 WHERE o.order_status=1 AND o.success_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 180 DAY) AND o.success_date<CURRENT_DATE()
)
SELECT CURRENT_DATE() AS dt,user_id,COUNT(*) AS metric_value
FROM orders GROUP BY user_id;

WITH active AS (
 SELECT DISTINCT user_id FROM gold_ods.app_login_log
 WHERE login_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY) AND login_date<CURRENT_DATE()
),orders AS (
 SELECT o.user_id,o.success_date,o.order_amount FROM gold_ods.infull_order o
 JOIN active a ON a.user_id=o.user_id
 WHERE o.order_status=1 AND o.success_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 180 DAY) AND o.success_date<CURRENT_DATE()
)
SELECT CURRENT_DATE() AS dt,user_id,DATEDIFF(CURRENT_DATE(),MAX(success_date)) AS metric_value
FROM orders GROUP BY user_id;
